//! Dependent signals retain native reasons, ordering and abort integrations.
use super::*;
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str)->Value{p.begin_job();p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap()}
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse_loaded_document("<!doctype html><html><body><div>Main</div></body></html>",&||Ok(())).unwrap();d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();p.set_location(&crate::navigation::address("https://abort-timeout.test/source",&crate::navigation::Location::home()).unwrap());assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn fire(d:&mut Document,f:&mut Forms,p:&mut Page){let due=p.next_timer_deadline().expect("actual native timer deadline");let out=p.poll_timer_at(d,f,due).expect("actual native timer task");assert_eq!(out.errors,0,"{}",p.report());}

#[test]
fn abort_signal_any_factory_empty_and_preaborted_use_real_identity_and_first_reason(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var descriptor=Object.getOwnPropertyDescriptor(AbortSignal,'any');if(typeof AbortSignal.any!=='function'||AbortSignal.any.length!==1||AbortSignal.any.name!=='any'||!descriptor.writable||!descriptor.enumerable||!descriptor.configurable)throw 'any static method';var empty=AbortSignal.any([]),second=AbortSignal.any([]);if(!(empty instanceof AbortSignal)||empty===second||empty.aborted||empty.reason!==undefined||empty.throwIfAborted()!==undefined)throw 'empty genuine signals';var reason={},a=AbortSignal.abort(reason),b=AbortSignal.abort(null),s=AbortSignal.any([a,b]),t=AbortSignal.any([b,a]);if(!s.aborted||s.reason!==reason||!t.aborted||t.reason!==null||s===a)throw 'first already aborted reason';var thrown;try{s.throwIfAborted();}catch(error){thrown=error;}if(thrown!==reason)throw 'dependent throw identity';var calls=0;s.addEventListener('abort',function(){calls++;});if(calls)throw 'preaborted must not fire';
"#);assert!(p.next_timer_deadline().is_none());}
#[test]
fn abort_signal_any_iterable_conversion_finishes_before_selection_and_preserves_abrupt_effects(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"if(typeof AbortSignal.any!=='function')throw 'missing any';var controller=new AbortController(),aborted=AbortSignal.abort('first');");let count=p.state.abort_signals.len();run(&mut d,&mut f,&mut p,r#"
var errors=0;for(var input of [undefined,null,1,'',{},[null],[{}],[aborted,{}]]){try{AbortSignal.any(input);}catch(error){if(error instanceof TypeError)errors++;}}try{AbortSignal.any();}catch(error){if(error instanceof TypeError)errors++;}if(errors!==9)throw 'sequence and signal brand TypeErrors';var marker={},log='',abrupt={};Object.defineProperty(abrupt,Symbol.iterator,{get:function(){log+='G';throw marker;}});try{AbortSignal.any(abrupt);}catch(error){if(error!==marker)throw 'iterator getter reason';}if(log!=='G')throw 'live iterator getter';
"#);assert_eq!(p.state.abort_signals.len(),count);run(&mut d,&mut f,&mut p,r#"
var log='',input={};input[Symbol.iterator]=function(){log+='I';var index=0;return {next:function(){log+='N';if(index++===0)return {done:false,value:controller.signal};return {done:true};}};};var s=AbortSignal.any(input);if(log!=='INN'||s.aborted)throw 'actual iterator sequence';controller.abort('iterated');if(!s.aborted||s.reason!=='iterated')throw 'iterated dependency';
"#);}
#[test]
fn abort_signal_any_flattened_dependencies_set_reasons_before_ordered_steps_and_nested_abort(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var root=new AbortController(),other=new AbortController(),reason={},a=AbortSignal.any([root.signal,other.signal,root.signal]),b=AbortSignal.any([a,root.signal,a]),c=AbortSignal.any([b,a]),target=new EventTarget(),linked=0,log='',afterSource=0;target.addEventListener('linked',function(){linked++;},{signal:a});root.signal.addEventListener('abort',function(){if(!a.aborted||!b.aborted||!c.aborted||a.reason!==reason||b.reason!==reason||c.reason!==reason||log)throw 'dependent reasons precede source steps';log+='R';var until=performance.now()+3;while(performance.now()<until){}afterSource=performance.now();target.dispatchEvent(new Event('linked'));if(linked!==1)throw 'dependent cleanup must await own steps';});a.addEventListener('abort',function(e){if(e.timeStamp<afterSource||e.target!==a||e.currentTarget!==a||!e.isTrusted||e.eventPhase!==2||e.composedPath().length!==1)throw 'actual dependent abort event';log+='A';target.dispatchEvent(new Event('linked'));if(linked!==1)throw 'dependent linked cleanup before callback';other.abort('nested loser');},{once:true});other.signal.addEventListener('abort',function(){log+='Q';});b.addEventListener('abort',function(e){if(e.timeStamp<afterSource)throw 'dependent event must be created at own step';log+='B';});c.addEventListener('abort',function(e){if(e.timeStamp<afterSource)throw 'later dependent event timestamp';log+='C';});root.abort(reason);if(log!=='RAQBC'||linked!==1||a.reason!==reason||b.reason!==reason||c.reason!==reason)throw 'flattened root creation order and reentry';root.abort('again');other.abort('again');if(log!=='RAQBC')throw 'first abort only';
"#);assert!(p.state.synthetic_dispatches.is_empty());}
#[test]
fn abort_signal_any_timeout_sources_and_loser_dependencies_do_not_repeat_delivery(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var timeout=AbortSignal.timeout(0),other=new AbortController(),a=AbortSignal.any([timeout,other.signal]),b=AbortSignal.any([a]),calls=0,reason;a.addEventListener('abort',function(){reason=a.reason;calls++;});b.addEventListener('abort',function(){if(b.reason!==a.reason)throw 'timeout propagated reason identity';calls++;});if(a.aborted||b.aborted||calls)throw 'timeout dependency asynchronous';
"#);fire(&mut d,&mut f,&mut p);run(&mut d,&mut f,&mut p,"if(calls!==2||!a.aborted||!b.aborted||reason!==timeout.reason||reason.name!=='TimeoutError')throw 'native timeout dependent delivery';other.abort('later');if(calls!==2||a.reason!==reason||b.reason!==reason)throw 'loser dependency must be detached';");assert!(p.next_timer_deadline().is_none());assert!(p.state.synthetic_dispatches.is_empty());}
#[test]
fn abort_signal_any_child_method_owner_and_saved_factory_guard_precede_iterator_effects(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var child=frame.contentWindow,childRoot=new child.AbortController(),savedSignal=childRoot.signal,factory=child.AbortSignal.any,ChildSignal=child.AbortSignal,root=new AbortController(),s=factory.call(null,[root.signal]),reason={},calls=0,iterations=0,arg={};arg[Symbol.iterator]=function(){iterations++;return {next:function(){return {done:true};}};};if(!(s instanceof ChildSignal)||s instanceof AbortSignal||s.aborted)throw 'dependent method realm independent source';s.addEventListener('abort',function(e){if(e.target!==s||!e.isTrusted||s.reason!==reason)throw 'child actual dependent delivery';calls++;});
"#);p.set_location(&crate::navigation::address("https://other.test/source",&crate::navigation::Location::home()).unwrap());let count=p.state.abort_signals.len();p.begin_job();let error=p.runtime.execute("factory(arg)",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("origin"),"{error}");assert_eq!(p.state.abort_signals.len(),count);p.begin_job();let error=p.runtime.execute("AbortSignal.any([savedSignal])",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("origin"),"{error}");assert_eq!(p.state.abort_signals.len(),count);p.begin_job();let error=p.runtime.execute("root.abort(reason)",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("origin"),"{error}");assert!(p.state.synthetic_dispatches.is_empty());p.set_location(&crate::navigation::address("https://abort-timeout.test/source",&crate::navigation::Location::home()).unwrap());run(&mut d,&mut f,&mut p,"if(iterations||root.signal.aborted||s.aborted)throw 'factory and batch authority refusal prefix';root.abort(reason);if(calls!==1||!s.aborted||s.reason!==reason)throw 'child dependent recovery';var fresh=AbortSignal.any([]);if(fresh.aborted)throw 'fresh main signal';");}
#[test]
fn abort_signal_any_factory_and_dependency_delivery_refusals_are_atomic_and_recover(){
 for profile in 0..4{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"if(typeof AbortSignal.any!=='function')throw 'missing any';var root=new AbortController();");while p.state.abort_signals.len()<p.state.abort_signals.capacity(){run(&mut d,&mut f,&mut p,"new AbortController();");}let before=(p.state.retained,p.state.abort_signals.len());let limit=p.state.retained_limit;p.begin_job();match profile{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,_=>p.state.execution_deadline=Some(Instant::now())}assert!(p.runtime.execute("AbortSignal.any([root.signal])",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).is_err());assert_eq!((p.state.retained,p.state.abort_signals.len()),before);p.state.retained_limit=limit;run(&mut d,&mut f,&mut p,"var recovered=AbortSignal.any([root.signal]);root.abort('fresh');if(!recovered.aborted||recovered.reason!=='fresh')throw 'factory fresh recovery';");}
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var root=new AbortController(),a=AbortSignal.any([root.signal]),b=AbortSignal.any([a]),calls=0;a.addEventListener('abort',function(){calls++;});b.addEventListener('abort',function(){calls++;});");let before=(p.state.retained,p.state.abort_signals.len(),p.state.listeners.len());let limit=p.state.retained_limit;p.state.retained_limit=p.state.retained;p.begin_job();assert!(p.runtime.execute("root.abort('refused')",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).is_err());assert_eq!((p.state.retained,p.state.abort_signals.len(),p.state.listeners.len()),before);assert!(p.state.synthetic_dispatches.is_empty());p.state.retained_limit=limit;run(&mut d,&mut f,&mut p,"if(root.signal.aborted||a.aborted||b.aborted||calls)throw 'batch refusal must have no reason prefix';root.abort('recovered');if(!a.aborted||!b.aborted||calls!==2||a.reason!=='recovered'||b.reason!=='recovered')throw 'dependency delivery recovery';");
 // Exhaust copying at several points in actual multi-event preparation. A
 // consumed native Event identity proves at least one refusal happened after
 // event construction; no reason/listener/event prefix may survive rollback.
 let mut refused_after_event=false;let mut admitted=false;
 for budget in [0,64,256,512,1024,2048,4096,8192]{
  let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var root=new AbortController(),a=AbortSignal.any([root.signal]),b=AbortSignal.any([a]),calls=0;a.addEventListener('abort',function(){calls++;});b.addEventListener('abort',function(){calls++;});");let events=p.state.created_events.len();let identity=p.state.next_event;let listeners=p.state.listeners.len();p.begin_job();p.state.copy_work=budget;
  let result=p.runtime.execute("root.abort('bounded')",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state});
  if result.is_err(){refused_after_event|=p.state.next_event>identity;assert_eq!(p.state.created_events.len(),events);assert_eq!(p.state.listeners.len(),listeners);assert!(p.state.synthetic_dispatches.is_empty());run(&mut d,&mut f,&mut p,"if(root.signal.aborted||a.aborted||b.aborted||calls)throw 'partial batch preparation prefix';root.abort('retry');if(calls!==2||a.reason!=='retry'||b.reason!=='retry')throw 'partial batch fresh recovery';");}
  else{admitted=true;run(&mut d,&mut f,&mut p,"if(!a.aborted||!b.aborted||calls!==2)throw 'admitted bounded batch';");}
 }
 assert!(refused_after_event,"actual post-construction batch rollback must be exercised");assert!(admitted);
 // Fatal delivery after the admitted reason commit unwinds every prepared
 // dispatch and removes remaining abort-linked registrations without callbacks.
 let(mut d,mut f,mut p)=fixture();let Value::Host(root)=run(&mut d,&mut f,&mut p,"var root=new AbortController(),a=AbortSignal.any([root.signal]),b=AbortSignal.any([a]),target=new EventTarget(),calls=0;target.addEventListener('linked',function(){calls++;},{signal:a});target.addEventListener('linked',function(){calls++;},{signal:b});a.addEventListener('abort',function(){calls++;});root;")else{panic!("genuine root")};p.begin_job();let steps=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.commit_abort_dispatch(root,Value::String("fatal".into())).unwrap();p.state.host_work=0;assert!(p.runtime.invoke_abort_dispatches(steps,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).is_err());assert!(p.state.synthetic_dispatches.is_empty());run(&mut d,&mut f,&mut p,"target.dispatchEvent(new Event('linked'));if(calls||!a.aborted||!b.aborted||a.reason!=='fatal'||b.reason!=='fatal')throw 'fatal admitted batch cleanup';var fresh=new AbortController(),dependent=AbortSignal.any([fresh.signal]);fresh.abort('fresh');if(dependent.reason!=='fresh')throw 'fatal batch fresh recovery';");
}
